<?php
// Customer identities are separate from CMS administrators. Ownership uses immutable IDs, never an unverified email match.
function customerSchema():void{static $done=false;if($done)return;$done=true;database()->exec('CREATE TABLE IF NOT EXISTS customers(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,hash TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,verified INTEGER NOT NULL DEFAULT 0,created TEXT NOT NULL); CREATE TABLE IF NOT EXISTS customer_tokens(token TEXT PRIMARY KEY,customer TEXT NOT NULL,purpose TEXT NOT NULL,expires INTEGER NOT NULL);');}
function customer():?array{customerSchema();sessionOpen();if(empty($_SESSION['customer'])||($_SESSION['customerExpires']??0)<time())return null;$c=sql('SELECT id,email,name,version,verified FROM customers WHERE id=?',[$_SESSION['customer']])->fetch(PDO::FETCH_ASSOC);return $c&&!accountDisabled($c['email'])&&(int)$c['version']===(int)($_SESSION['customerVersion']??0)?$c:null;}
function customerSignIn(array $c):void{accountLoginRecorded($c['email']);sessionOpen();session_regenerate_id(true);$_SESSION['customer']=$c['id'];$_SESSION['customerVersion']=(int)$c['version'];$_SESSION['customerExpires']=time()+86400*7;$_SESSION['csrf']=bin2hex(random_bytes(24));}
function customerPublic(?array $c):?array{return $c?array_intersect_key($c,array_flip(['id','email','name','verified'])):null;}
function customerToken(array $c,string $purpose):string{$token=bin2hex(random_bytes(32));sql('DELETE FROM customer_tokens WHERE customer=? AND purpose=? OR expires<?',[$c['id'],$purpose,time()]);sql('INSERT INTO customer_tokens VALUES(?,?,?,?)',[hash('sha256',$token),$c['id'],$purpose,time()+($purpose==='reset'?3600:86400)]);return $token;}
function customerVerifyMail(array $c):bool{if(empty(smtpConfig()['password']))return false;$token=customerToken($c,'verify');return notifyMail($c['email'],'Verify your Desert Sky account',"Hello ".$c['name'].",\n\nVerify your email address using this link within 24 hours:\n".ORIGIN.'/account/verify?token='.$token."\n\nIf you did not create this account, you can ignore this message.");}
function customerRegister(array $v):array{customerSchema();$email=strtolower(trim((string)($v['email']??'')));$name=text($v['name']??'',150);$password=(string)($v['password']??'');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>254||mb_strlen($name)<2||strlen($password)<12||strlen($password)>200)respond(['error'=>'Enter your name, a valid email and a password of 12–200 characters.'],422);if(sql('SELECT id FROM customers WHERE email=?',[$email])->fetchColumn())respond(['error'=>'An account already uses this email. Sign in or use password recovery.'],409);$c=['id'=>bin2hex(random_bytes(16)),'email'=>$email,'name'=>$name,'hash'=>password_hash($password,PASSWORD_DEFAULT),'version'=>1,'verified'=>0];sql('INSERT INTO customers(id,email,name,hash,version,verified,created) VALUES(?,?,?,?,1,0,?)',[$c['id'],$email,$name,$c['hash'],gmdate('c')]);customerSignIn($c);customerVerifyMail($c);return $c;}
function customerCheckoutIdentity(array $v):?array{$c=customer();if(!empty($v['createAccount'])&&!$c){throttle('customer-register',6,3600);$c=customerRegister($v);}if($c&&strtolower(trim((string)$v['email']))!==$c['email'])respond(['error'=>'Use your account email for this booking, or sign out to book as a guest.'],422);return $c;}
function customerBookings(string $id):array{$rows=array_values(array_filter(records('bookings',true),fn($b)=>($b['customerId']??'')===$id&&($b['paymentStatus']??'')==='paid'));usort($rows,fn($a,$b)=>strcmp($b['paidAt']??'',$a['paidAt']??''));return array_map(fn($b)=>array_intersect_key($b,array_flip(['id','reference','tourTitle','tourId','tourSlug','date','name','email','phone','pickup','notes','adults','children','units','addons','total','amount','currency','mode','paidAt','paymentStatus','status','items'])),$rows);}
function validTourDate($value):string{$date=(string)$value;$dt=DateTimeImmutable::createFromFormat('!Y-m-d',$date,new DateTimeZone('Asia/Dubai'));$today=new DateTimeImmutable('today',new DateTimeZone('Asia/Dubai'));if(!$dt||$dt->format('Y-m-d')!==$date||$dt<$today||$dt>$today->modify('+18 months'))respond(['error'=>'Choose a valid future tour date.'],422);return $date;}
function availableTour(string $id):?array{$t=getRecord('tours',$id);return $t&&empty($t['deletedAt'])&&($t['status']??'')==='published'&&substr($t['publishedAt']??'2000-01-01',0,10)<=gmdate('Y-m-d')?$t:null;}
function cartRows():array{sessionOpen();$paid=!empty($_SESSION['checkoutId'])?getRecord('bookings',$_SESSION['checkoutId']):null;if($paid&&($paid['paymentStatus']??'')==='paid'){foreach($paid['cartIds']??[] as $id)unset($_SESSION['cart'][$id]);}$rows=[];foreach($_SESSION['cart']??[] as $id=>$line){$t=availableTour($line['tourId']);$guests=$line['adults']+$line['children'];$capacity=max(1,(int)($t['capacity']??7));$overCapacity=$t&&((($t['pricingMode']??'')==='per_group'&&$guests>$line['units']*$capacity)||(($t['pricingMode']??'')==='per_hour'&&$guests>$capacity));$invalid=!$t||$overCapacity||price($t)<=0||$line['date']<(new DateTimeImmutable('today',new DateTimeZone('Asia/Dubai')))->format('Y-m-d');if($invalid){$rows[]=['id'=>$id,'available'=>false,'title'=>$t['title']??'Unavailable experience','image'=>$t['image']??'/assets/dubai.webp','input'=>$line];continue;}$quote=bookingQuote($t,$line);$rows[]=['id'=>$id,'available'=>true,'title'=>$t['title'],'slug'=>$t['slug'],'image'=>$t['image'],'input'=>$line,'quote'=>$quote];}return $rows;}
function checkoutCart(array $v):never{throttle('checkout',12,600);if(!paymentReady())respond(['error'=>'Online payment is not connected yet. Your cart is saved. Please contact our team.'],503);$rows=cartRows();if(!$rows||count($rows)>10)respond(['error'=>'Add between 1 and 10 experiences to your cart.'],422);$email=filter_var($v['email']??'',FILTER_VALIDATE_EMAIL);$name=text($v['name']??'',150);$phone=text($v['phone']??'',50);if(!$email||strlen($name)<2||strlen(preg_replace('/\D/','',$phone))<7||empty($v['acceptedTerms'])||!empty($v['website']))respond(['error'=>'Enter your contact details and accept the booking terms.'],422);$items=[];$total=0;$stripeLines=[];foreach($rows as $row){if(!$row['available'])respond(['error'=>'Remove unavailable or expired experiences before checkout.'],422);validTourDate($row['input']['date']);$t=availableTour($row['input']['tourId']);$q=bookingQuote($t,$row['input']);$total+=$q['amount'];$item=array_merge($q,['tourId'=>$t['id'],'tourSlug'=>$t['slug'],'tourTitle'=>$t['title'],'date'=>$row['input']['date']]);$items[]=$item;$stripeLines[]=['price_data'=>['currency'=>'aed','product_data'=>['name'=>$t['title'].' — '.$item['date'],'description'=>($q['adults']+$q['children']).' guests'],'unit_amount'=>$q['amount']],'quantity'=>1];}$c=customerCheckoutIdentity($v);$id=bin2hex(random_bytes(16));$first=$items[0];$config=paymentConfig();$b=array_merge($first,['id'=>$id,'reference'=>'DST-'.strtoupper(substr($id,0,8)),'tourTitle'=>count($items)===1?$first['tourTitle']:count($items).' UAE experiences','total'=>$total/100,'amount'=>$total,'items'=>$items,'cartIds'=>array_column($rows,'id'),'customerId'=>$c['id']??'','name'=>$name,'email'=>strtolower($email),'phone'=>$phone,'pickup'=>text($v['pickup']??'',300),'notes'=>text($v['notes']??'',1200),'createdAt'=>gmdate('c'),'mode'=>$config['mode'],'sessionToken'=>bin2hex(random_bytes(24))]);putRecord('checkout',$id,$b);$session=stripeRequest('POST','checkout/sessions',['mode'=>'payment','customer_email'=>$email,'client_reference_id'=>$id,'success_url'=>ORIGIN.'/thank-you?session_id={CHECKOUT_SESSION_ID}','cancel_url'=>ORIGIN.'/cart?cancelled=1','line_items'=>$stripeLines,'metadata'=>['booking_id'=>$id],'expires_at'=>time()+1800],null,'dst-checkout-'.$id);if(!str_starts_with($session['url']??'','https://checkout.stripe.com/'))throw new RuntimeException('Invalid checkout destination.');$b['sessionId']=$session['id'];putRecord('checkout',$id,$b);sessionOpen();$_SESSION['checkoutId']=$id;$_SESSION['checkoutToken']=$b['sessionToken'];respond(['url'=>$session['url']]);}
function commerceIcon(string $name):string{$paths=['cart'=>'<circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/><path d="M1 1h4l2.7 13.4a2 2 0 0 0 2 1.6h9.7a2 2 0 0 0 2-1.6L23 6H6"/>','user'=>'<circle cx="12" cy="8" r="4"/><path d="M4 22v-2a8 8 0 0 1 16 0v2"/>'];return '<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'.($paths[$name]??$paths['user']).'</svg>';}
function checkoutAccountFields():string{$c=customer();ob_start();if($c):?><div class="account-checkout-note"><?=commerceIcon('user')?><div><strong>Booking as <?=esc($c['name'])?></strong><p>Your paid booking will appear in <a href="/account">My bookings</a>.</p></div></div><?php else:?><section class="checkout-account"><h3>Keep every adventure in one place.</h3><p><a href="/account/sign-in?return=<?=rawurlencode($_SERVER['REQUEST_URI'])?>">Already have an account? Sign in.</a></p><label class="terms-checkbox"><input type="checkbox" name="createAccount" data-create-account><span>Create a customer account with my booking details</span></label><div data-account-password hidden><label>Create a password<input name="password" type="password" minlength="12" maxlength="200" autocomplete="new-password" data-new-account-password></label><small>Use at least 12 characters. Your account can be used even if you do not complete payment. Creating an account agrees to our <a href="/terms">terms</a> and <a href="/privacy">privacy policy</a>.</small></div></section><?php endif;return ob_get_clean();}
